<?php
require_once __DIR__.'/../includes/functions.php';admin_required();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=in_array($_POST['status']??'', ['approved','hidden','pending'],true)?$_POST['status']:'pending';try{$q=db()->prepare('UPDATE wishes SET status=? WHERE id=?');$q->execute([$status,$id]);$message='Status ucapan diperbarui.';}catch(Throwable){$message='Gagal memperbarui ucapan.';}}$items=[];try{$items=db()->query('SELECT w.*,i.slug FROM wishes w JOIN invitations i ON i.id=w.invitation_id ORDER BY w.created_at DESC')->fetchAll();}catch(Throwable){}$page_title='Moderasi Ucapan';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">MODERATION</span><h1>Ucapan</h1></header><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif;?><section class="table-wrap"><table><thead><tr><th>Nama</th><th>Ucapan</th><th>Invitation</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['name'])?></td><td><?=e($item['message'])?></td><td><?=e($item['slug'])?></td><td><?=e($item['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)$item['id'])?>"><select name="status"><option value="approved">Approve</option><option value="hidden">Hide</option><option value="pending">Pending</option></select><button class="button" type="submit">Simpan</button></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Belum ada ucapan.</td></tr><?php endif;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
